//! Branch/window names generated by Pi from the current diff.

use std::io::Write;

use crate::common::{
    BLUE, Ctx, Fail, RESET, Res, capture_quiet, chomp, die, report, run_with_input,
    split_first_tab, tty_print_lenient, tty_read_into,
};

/// Which changes the names describe.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    /// Staged changes (`create`).
    Staged,
    /// Working tree and index changes (`rename`).
    Current,
}

const RULES: &str = r#"Return ONLY compact JSON with this shape:
{"branch":"kebab-case-branch-name","window":"short-window-name"}

Rules:
- branch must be a valid git branch name suitable for a PR.
- Do not add generic prefixes like feature/, fix/, worktree/ unless the project diff clearly indicates that convention.
- branch: kebab-case, descriptive, preferably 2-5 words.
- window: short for tmux status, kebab-case, preferably 1-3 words and under 18 chars.
- No markdown, no explanation."#;

const DIFF_LIMIT: usize = 204_800;

/// A git diff for LLM naming only: secret/noise paths excluded, size capped.
pub fn naming_diff(ctx: &Ctx, args: &[&str]) -> String {
    let mut command = ctx.git(["diff"]);
    command.args(args).arg("--").args(&ctx.cfg.diff_pathspecs);
    let out = capture_quiet(&mut command).1;
    let capped: String = out.chars().take(DIFF_LIMIT).collect();
    format!("{capped}\n")
}

/// The full Pi prompt for a mode.
pub fn naming_prompt(ctx: &Ctx, mode: Mode) -> String {
    match mode {
        Mode::Staged => format!(
            "Generate names for a git worktree task from the staged changes.\n\n{RULES}\n\nStaged changes:\n\n{}\n{}",
            naming_diff(ctx, &["--cached", "--stat"]),
            naming_diff(ctx, &["--cached"]),
        ),
        Mode::Current => format!(
            "Generate a new git branch name and short tmux window name from the current repository changes.\n\n{RULES}\n\nCurrent changes:\n\n{}\n{}\n{}\n{}",
            naming_diff(ctx, &["--stat", "HEAD"]),
            naming_diff(ctx, &["HEAD"]),
            naming_diff(ctx, &["--cached", "--stat"]),
            naming_diff(ctx, &["--cached"]),
        ),
    }
}

fn find_on_path(program: &str) -> bool {
    std::env::var_os("PATH").is_some_and(|paths| {
        std::env::split_paths(&paths).any(|dir| {
            let candidate = dir.join(program);
            std::fs::metadata(&candidate).is_ok_and(|meta| {
                use std::os::unix::fs::PermissionsExt;
                meta.is_file() && meta.permissions().mode() & 0o111 != 0
            })
        })
    })
}

/// Run Pi on the prompt; on failure its stderr is shown and the output is empty.
fn run_pi(ctx: &Ctx, prompt: &str) -> String {
    if !find_on_path("pi") {
        report(&Fail::Die("pi CLI not found".into()));
        return String::new();
    }
    let mut args: Vec<&str> = vec!["--print"];
    if let Some(model) = &ctx.cfg.model {
        args.extend(["--model", model]);
    }
    if let Some(thinking) = &ctx.cfg.thinking {
        args.extend(["--thinking", thinking]);
    }
    args.extend([
        "--no-session",
        "--no-tools",
        "--no-extensions",
        "--no-skills",
        "--no-prompt-templates",
        "--no-context-files",
    ]);
    let mut command = ctx.command("pi");
    command.args(&args);
    match run_with_input(&mut command, prompt.as_bytes()) {
        Ok((0, stdout, _)) => chomp(&String::from_utf8_lossy(&stdout)),
        Ok((_, _, stderr)) => {
            let _ = std::io::stderr().write_all(&stderr);
            String::new()
        }
        Err(err) => {
            eprintln!("worktree: pi: {}", crate::common::io_message(&err));
            String::new()
        }
    }
}

/// What `jq -r '.<key>'` prints for each JSON value in `text`, stopping at the
/// first error (jq's own exit status was ignored by the original).
pub fn jq_field(text: &str, key: &str) -> String {
    let mut lines = Vec::new();
    for value in serde_json::Deserializer::from_str(text).into_iter::<serde_json::Value>() {
        let Ok(value) = value else { break };
        let field = match &value {
            serde_json::Value::Object(map) => map.get(key).cloned().unwrap_or_default(),
            serde_json::Value::Null => serde_json::Value::Null,
            _ => break,
        };
        lines.push(match field {
            serde_json::Value::String(text) => text,
            other => serde_json::to_string_pretty(&other).unwrap_or_default(),
        });
    }
    chomp(&lines.join("\n"))
}

/// Ask Pi for names; returns `branch<TAB>window` as the original printed it.
pub fn generate_names(ctx: &Ctx, mode: Mode) -> Res<String> {
    let output = run_pi(ctx, &naming_prompt(ctx, mode));
    let branch = jq_field(&output, "branch");
    let window = jq_field(&output, "window");
    if branch.is_empty() || window.is_empty() {
        return die(format!(
            "Could not parse generated names from Pi output: {output}"
        ));
    }
    Ok(format!("{branch}\t{window}"))
}

/// Show names and ask `<action>? [Y/n/e/r]` until accepted.
pub fn confirm_names(
    ctx: &Ctx,
    mode: Mode,
    action: &str,
    mut branch: String,
    mut window: String,
) -> Res<(String, String)> {
    let mut response = String::new();
    let mut new_branch = String::new();
    let mut new_window = String::new();
    loop {
        tty_print_lenient(&format!("\n{BLUE}Branch:{RESET} {branch}\n"));
        tty_print_lenient(&format!("{BLUE}Window:{RESET} {window}\n\n"));
        tty_read_into(&format!("{action}? [Y/n/e/r] "), &mut response);
        if response.is_empty() {
            response = "Y".into();
        }
        match response.chars().next() {
            Some('Y' | 'y') => return Ok((branch, window)),
            Some('N' | 'n') => return die("Cancelled"),
            Some('E' | 'e') => {
                tty_read_into(&format!("Branch [{branch}]: "), &mut new_branch);
                tty_read_into(&format!("Window [{window}]: "), &mut new_window);
                if !new_branch.is_empty() {
                    branch.clone_from(&new_branch);
                }
                if !new_window.is_empty() {
                    window.clone_from(&new_window);
                }
            }
            Some('R' | 'r') => {
                let generated = generate_names(ctx, mode).unwrap_or_else(|fail| {
                    report(&fail);
                    String::new()
                });
                (branch, window) = split_first_tab(&generated);
            }
            _ => {
                tty_print_lenient("Please answer Y, n, e, or r.\n");
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn jq_field_matches_jq_raw_output() {
        assert_eq!(
            jq_field(r#"{"branch":"a-b","window":"w"}"#, "branch"),
            "a-b"
        );
        assert_eq!(jq_field(r#"{"window":"w"}"#, "branch"), "null");
        assert_eq!(jq_field("not json", "branch"), "");
        assert_eq!(jq_field(r#""text""#, "branch"), "");
        assert_eq!(jq_field("", "branch"), "");
        assert_eq!(jq_field(r#"{"branch":1}"#, "branch"), "1");
    }
}
